/* course13.js — Course 13 content (OT/ICS: industrial network security; loaded on demand via course-core.js) */
/* ============================================================
   COURSE 13 — OT/ICS: industrial network security (what OT is, the Purdue model,
   industrial protocols, the data diode, attacks on OT, defense and operations).
   Practically follows the OT/ICS preset and the ch-otseg challenge in the simulator.
   Scene c13Net: IT-PC + ENG — FW — HIST (DMZ) / HMI — PLC — DIODE.
   ============================================================ */
var C13R={it:[70,56],eng:[70,160],fw:[210,110],hist:[350,56],hmi:[350,160],plc:[510,160],dio:[510,56]};
function c13Net(pfx){
  return '<svg id="'+pfx+'svg" viewBox="0 0 640 216" width="100%" style="display:block">'
    +'<line x1="85" y1="62" x2="195" y2="104" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="85" y1="154" x2="195" y2="116" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="225" y1="104" x2="335" y2="62" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="225" y1="116" x2="335" y2="154" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="366" y1="160" x2="494" y2="160" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="510" y1="144" x2="510" y2="72" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="494" y1="56" x2="366" y2="56" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<g id="'+pfx+'glow"></g>'
    +csHost(70,56,'desktop','--blue','IT-PC')+csHost(70,160,'laptop','--cyan','ENG')
    +csDev(210,110,'firewall','FW')
    +csHost(350,56,'historian','--violet','HIST')+csHost(350,160,'hmi','--green','HMI')
    +csHost(510,160,'plc','--amber','PLC')+csDev(510,56,'datadiode','DIODE')
    +'<g id="'+pfx+'dyn"></g></svg>';
}
function c13P(pfx,intro,terms){
  return '<p style="color:var(--muted);font-size:var(--crs-fs,13.5px);line-height:1.55;margin:0 0 10px">'+intro+'</p>'
    +'<div class="osi-stage">'+c13Net(pfx)+'</div><div class="m1-cap" id="'+pfx+'cap"></div>'
    +courseStepControls(pfx)+abbrBox(terms);
}
function c13Mount(pfx,STEPS){
  function show(i){var g=$(pfx+'glow');if(g)g.innerHTML=STEPS[i].glow||'';var d=$(pfx+'dyn');if(d)d.innerHTML=STEPS[i].dyn||'';var c=$(pfx+'cap');if(c)c.innerHTML='<span>'+STEPS[i].cap+'</span>';}
  courseStepper(pfx,STEPS.length,show);
}
function c13g(name,color){var p=C13R[name];return csGlow(p[0],p[1],color,20);}
function c13lbl(x,y,tx,c){return '<text x="'+x+'" y="'+y+'" text-anchor="middle" style="font:700 7.5px var(--mono);fill:var('+c+')">'+esc(tx)+'</text>';}
function c13pkt(path,color,dur){return '<rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var('+color+')"><animateMotion path="'+path+'" dur="'+(dur||'1.4s')+'" repeatCount="indefinite"/></rect>';}

/* ---------- L1M1 — The network that moves things ---------- */
function renderC13WhatIsOt(){return c13P('ota',
  'So far our courses lived in the <b>IT</b> world: computers, servers, websites – the network moves <b>information</b>. Now we enter a world where the network moves <b>real things</b>: conveyor belts in a factory, valves in a water plant, turbines in a power station. It is called <b>OT</b> (Operational Technology) and its networked form <b>ICS</b> (Industrial Control Systems). Meet the main devices on the scene: a <b>PLC</b> (programmable logic controller) is a small rugged computer bolted next to a machine – it reads sensors and switches motors or valves; it is the hand that actually moves things. An <b>HMI</b> (Human-Machine Interface) is a touch panel or a control room from which an operator watches and drives production – it sends commands to the PLC. A <b>historian</b> is a database that continuously stores values from production (temperatures, pressures, piece counts) so the rest of the company can look at them. And the supervisory system above it all is called <b>SCADA</b>. Why does this belong in a security course? Because when IT fails, you lose data. When OT fails, <b>production stops – or a boiler blows</b>. The firewall (FW) and the data diode (DIODE) on the scene will make sense in later lessons.',
  [['PLC','a programmable controller next to a machine – reads sensors, switches motors and valves; the device that actually moves things.'],['HMI','the operator’s panel or control room – shows production state and sends commands to the PLC.'],['historian','a database storing production values (temperatures, pressures) for the rest of the company.'],['SCADA','the supervisory control and data acquisition system above the whole plant.']]);}
function mountC13WhatIsOt(){c13Mount('ota',[
  {glow:c13g('plc','--amber'),dyn:c13lbl(430,211,'PLC: reads sensors, switches valves','--amber'),cap:'A <b>PLC</b> is a rugged computer next to a machine. It reads sensors and switches motors or valves – it <b>moves real things</b>.'},
  {glow:c13g('hmi','--green')+c13g('plc','--green'),dyn:c13pkt('M 366 160 L 494 160','--green')+c13lbl(430,211,'HMI → PLC: operator command','--green'),cap:'From the <b>HMI</b> (panel, control room) the operator watches and drives production – sending the PLC commands. The supervision above it is <b>SCADA</b>.'},
  {glow:c13g('plc','--violet')+c13g('dio','--violet')+c13g('hist','--violet'),dyn:c13pkt('M 510 144 L 510 56 L 366 56','--violet')+c13lbl(430,108,'production data → historian','--violet'),cap:'The <b>historian</b> continuously stores production values (temperatures, pressures, counts) so the rest of the company can see them.'},
  {glow:c13g('plc','--red'),dyn:c13lbl(430,211,'OT failure = production stops ⚠','--red'),cap:'Why security? When IT fails, you lose <b>data</b>. When OT fails, <b>production stops</b> – or physical damage happens.'}
]);}
/* ---------- L1M2 — Availability above all ---------- */
function renderC13Availability(){return c13P('otb',
  'In IT security you learned the <b>CIA</b> priority order: confidentiality first, then integrity, availability last. In OT the order is <b>exactly reversed</b>: <b>availability &gt; integrity &gt; confidentiality</b>. Why? Picture a bottling line. If someone ‘reads’ how many bottles per hour you fill, it is unpleasant – but production runs. If the line <b>stops</b>, every minute costs money, restarting takes hours, and for some processes (a melting furnace, chemicals) an outage can mean <b>destroyed equipment or danger to people</b>. From this priority follows behavior that surprises IT folks: in OT you do not <b>reboot</b> ‘just in case’, you do not <b>install</b> updates mid-shift, and a security measure that could take production down is worse than none. Even a well-meant action – a network scan, an agent on a workstation – can knock over sensitive control systems (more in lesson 6). Remember this as the key to the whole course: every OT measure is judged first by <b>‘can it stop production?’</b> – and only then by ‘does it improve security?’.',
  [['availability first','in OT the order is availability > integrity > confidentiality – the reverse of IT (CIA).'],['cost of downtime','a stopped line = money, hours of restart, for some processes even physical damage or danger.']]);}
function mountC13Availability(){c13Mount('otb',[
  {glow:c13g('it','--blue'),dyn:c13lbl(160,20,'1. confidentiality','--blue')+c13lbl(160,36,'2. integrity','--blue')+c13lbl(160,52,'3. availability','--muted')+c13lbl(160,211,'IT: confidentiality > integrity > availability','--blue'),cap:'In <b>IT</b> you mainly protect data: the CIA order – confidentiality, integrity, availability.'},
  {glow:c13g('plc','--amber')+c13g('hmi','--amber'),dyn:c13lbl(430,20,'1. availability','--amber')+c13lbl(430,36,'2. integrity','--amber')+c13lbl(430,52,'3. confidentiality','--muted')+c13lbl(430,211,'OT: availability > integrity > confidentiality','--amber'),cap:'In <b>OT</b> the order is reversed: <b>availability above all</b>. The line must run.'},
  {glow:c13g('plc','--red')+c13g('hmi','--red'),dyn:'<line x1="366" y1="160" x2="494" y2="160" style="stroke:var(--red);stroke-width:2.4;stroke-dasharray:3 3"/>'+c13lbl(430,150,'✕','--red')+c13lbl(430,20,'the line is stopped ⚠','--red')+c13lbl(430,211,'outage: money, damage, risk to people ⚠','--red'),cap:'Stopped production costs money every minute; with furnaces or chemicals it risks <b>destroyed equipment</b> or danger to people.'},
  {glow:c13g('it','--green')+c13g('fw','--green')+c13g('hist','--green'),dyn:c13pkt('M 85 62 L 195 104','--green')+c13pkt('M 225 104 L 335 62','--green','1.4s')+c13lbl(160,20,'the measure passed: it will not stop production','--green')+c13lbl(160,211,'the test: ‘can it stop production?’','--green'),cap:'The key: judge every OT measure first by <b>‘can it stop production?’</b> – only then by ‘does it improve security?’.'}
]);}
/* ---------- L1M3 — Twenty years without a patch ---------- */
function renderC13Legacy(){return c13P('otc',
  'The second culture shock for an IT person: <b>equipment age</b>. You replace a laptop after five years, a server after seven. PLCs and control systems are bought with the production line and serve <b>20 or 30 years</b> – as long as the line runs. Inside often runs an <b>old system</b> (Windows XP in a control room is not a joke but common reality) that has had <b>no patches for years</b>. And even if patches existed: an update means an outage and the risk the line will not restart – and the line’s vendor often <b>forbids</b> touching the system, or you lose warranty and certification. The result: an OT network is full of devices with <b>known, never-fixed holes</b> – which nobody may or can fix. What then? Flip the approach: when I cannot fix the <b>device</b>, I must protect the <b>network around it</b>. I wrap the vulnerable PLC in segmentation and a firewall so an attacker <b>never reaches it</b> – a hole nobody can reach cannot be exploited. This is called a <b>compensating control</b> and it is the main reason the rest of this course is about segmentation, one-way flows and monitoring, not patching.',
  [['20+ year lifetime','control systems serve with the line for decades; old, unpatched systems run inside.'],['compensating control','when the device cannot be fixed, protect the network around it – segmentation, firewall, monitoring.']]);}
function mountC13Legacy(){c13Mount('otc',[
  {glow:c13g('plc','--amber'),dyn:c13lbl(430,211,'a PLC serves 20–30 years','--amber'),cap:'PLCs and control systems are bought <b>with the line</b> and serve for decades – as long as the line runs.'},
  {glow:c13g('hmi','--red')+c13g('plc','--red'),dyn:c13lbl(430,211,'old systems, no patches ⚠','--red'),cap:'Inside run <b>old systems without patches</b>; an update = outage + risk + often a vendor ban.'},
  {glow:c13g('fw','--green')+c13g('plc','--green'),dyn:c13lbl(430,211,'can’t fix the device → protect the network','--green'),cap:'Flip the approach: a hole an attacker <b>cannot reach</b> cannot be exploited. Wrap the vulnerable PLC in segmentation and a firewall.'},
  {glow:c13g('fw','--cyan'),dyn:c13lbl(160,211,'= compensating controls (rest of the course)','--cyan'),cap:'These are <b>compensating controls</b> – which is why the rest of the course is about segmentation, one-way flows and monitoring.'}
]);}
/* ---------- L2M1 — The Purdue model: the factory's floors ---------- */
function renderC13Purdue(){return c13P('otd',
  'How do you find your way around an industrial network? A map called the <b>Purdue model</b> is used: it splits the plant into <b>levels 0–4</b> by how close they are to the physical process. <b>Level 0</b>: sensors and actuators – thermometers, valves, motors. <b>Level 1</b>: the <b>PLC</b> that reads and drives them. <b>Level 2</b>: supervision and control – the <b>HMI</b>, the control room, SCADA. <b>Level 3</b>: managing production as a whole (shift planning, recipe management). And on top <b>level 4</b>: ordinary corporate <b>IT</b> – email, accounting, offices. On our scene: IT-PC is level 4, the HMI level 2, the PLC level 1. What is the map for? It gives the network admin and the plant engineer a shared language: ‘this traffic belongs to level 2, nothing from level 4 goes through here’. Above all it defines <b>boundaries</b>: between levels (mainly between 3 and 4 – between OT and IT) you build a <b>firewall</b>, and traffic is allowed only rarely and deliberately. The lower you are in the model, the more sensitive the network and the fewer things may enter it. How exactly to build the IT/OT boundary is shown in the next two modules.',
  [['Purdue model','a map of an industrial network: levels 0–4 by closeness to the physical process.'],['levels 0–2 (OT)','sensors and valves (0), PLC (1), HMI/control room/SCADA (2) – the lower, the more sensitive.'],['level 4 (IT)','the ordinary corporate network – e-mail, accounting; it enters OT only through a guarded boundary.']]);}
function mountC13Purdue(){
  var L01=function(){return c13lbl(560,160,'L0-1','--amber');};
  var L2=function(){return c13lbl(300,160,'L2','--green');};
  var L4=function(){return c13lbl(24,56,'L4','--blue')+c13lbl(24,160,'L4','--blue');};
  c13Mount('otd',[
  {glow:c13g('plc','--amber'),dyn:L01()+c13lbl(430,211,'levels 0–1: sensors, valves, PLC','--amber'),cap:'At the bottom <b>level 0</b> (sensors, valves, motors) and <b>level 1</b> (the PLC driving them). The most sensitive floors.'},
  {glow:c13g('hmi','--green'),dyn:L01()+L2()+c13lbl(430,211,'level 2: HMI, control room, SCADA','--green'),cap:'<b>Level 2</b>: supervision and control – HMI, control room, SCADA. Level 3 then manages production as a whole.'},
  {glow:c13g('it','--blue')+c13g('eng','--blue'),dyn:L01()+L2()+L4()+c13lbl(160,211,'level 4: ordinary corporate IT','--blue'),cap:'On top <b>level 4</b>: offices, email, accounting – the ordinary corporate IT network.'},
  {glow:c13g('it','--red')+c13g('fw','--red'),dyn:L01()+L2()+L4()+c13pkt('M 85 62 L 190 102','--red')+c13lbl(210,78,'✕','--red')+c13lbl(160,211,'the IT/OT boundary = a firewall','--red'),cap:'Between levels you build <b>boundaries</b> – mainly between IT and OT stands a firewall, and traffic is allowed only deliberately.'}
]);}
/* ---------- L2M2 — Why IT must not reach the PLC directly ---------- */
function renderC13ItOt(){return c13P('ote',
  'Why so strict? It would be <b>convenient</b> for the production manager to look at the PLC straight from the office… But think through what a direct link means. The office network (level 4) is the <b>dirtiest</b> part of the company: people click attachments, browse the web, bring their own devices – malware shows up there <b>routinely</b>. If a direct path led from it to the PLC, every infected office PC is <b>one hop from production</b>. And recall lesson 1: the PLC is twenty years old, unpatched, and if it drops, the line stops. A direct IT→PLC link thus connects <b>the dirtiest network to the most vulnerable device</b> – the worst possible combination. Hence the rule: <b>the IT network never touches the PLC directly</b>. Between IT and OT stands a firewall (FW on the scene) with a <b>default-deny</b> policy: what is not explicitly allowed is forbidden – the same rule you know from the course <i>Network security</i>, only here it guards a boundary between two internal worlds, not the internet edge. Yet production does need to share data (the manager really wants those numbers). How to get them out without a path leading in? That is the job of the <b>industrial DMZ</b> – next module.',
  [['default-deny at the boundary','the IT/OT firewall: what is not explicitly allowed is forbidden – even between internal networks.'],['one hop from production','a direct IT→PLC path means every infected office PC threatens the line.']]);}
function mountC13ItOt(){c13Mount('ote',[
  {glow:c13g('it','--red'),dyn:c13lbl(160,211,'the office network = the dirtiest','--red'),cap:'Level 4 is the <b>dirtiest</b>: attachments, web, personal devices – malware shows up here routinely.'},
  {glow:c13g('it','--red')+c13g('fw','--red')+c13g('hmi','--red')+c13g('plc','--red'),dyn:c13pkt('M 85 62 L 210 110 L 350 160 L 494 160','--red')+c13lbl(430,211,'a direct IT → PLC path ⚠','--red'),cap:'A direct IT→PLC link = <b>the dirtiest network + the most vulnerable device</b>. An infected PC is one hop from production.'},
  {glow:c13g('fw','--green'),dyn:c13lbl(160,211,'the IT/OT FW: default-deny','--green'),cap:'So between IT and OT stands a <b>default-deny firewall</b>: what is not explicitly allowed is forbidden (the course <i>Network security</i>).'},
  {glow:c13g('hist','--violet'),dyn:c13lbl(430,108,'and data out? → the industrial DMZ','--violet'),cap:'Yet production needs to share data. How to get it out with no path in? The <b>industrial DMZ</b> – next module.'}
]);}
/* ---------- L2M3 — The industrial DMZ and the middleman ---------- */
function renderC13Dmz(){return c13P('otf',
  'From the course <i>Network security</i> you know the <b>DMZ</b>: an anteroom between the internet and the inner network where you put the web server so strangers do not come inside. Industry uses the same trick <b>between IT and OT</b>: it builds an <b>industrial DMZ</b> (called level 3.5 in the Purdue model, because it sits exactly between level 3 – production management – and level 4 – corporate IT) and places the <b>historian</b> there – a data middleman. The flow looks like this: from the <b>OT side</b> the historian continuously pulls production values and stores them; from the <b>IT side</b> anyone authorized queries the historian (a database query) and reads the numbers. What matters is what the firewall allows: <b>IT → historian: YES</b> (the database port only), <b>IT → PLC: NO</b>, <b>OT → historian: YES</b> (data collection). No rule leads from IT into OT! The production manager has his numbers – and yet <b>no path exists</b> for office malware to hop onto the PLC: it gets at most to the historian, which (unlike the PLC) is modern, patched and expendable – if it fell, production keeps running. Note the general principle, you will meet it across OT security: <b>data is handed over via a middleman in the DMZ, never by a direct link</b> between a dirty and a sensitive network. The ‘OT/ICS network’ preset in the simulator is built exactly this way – you will try it in lesson 3.',
  [['industrial DMZ (3.5)','an anteroom between IT and OT; the historian lives here as the data middleman.'],['middleman','IT reads the historian, the historian collects from OT – no rule leads from IT straight into OT.']]);}
function mountC13Dmz(){c13Mount('otf',[
  {glow:c13g('hist','--violet')+c13g('fw','--violet'),dyn:c13lbl(430,108,'the historian lives in the DMZ (level 3.5)','--violet'),cap:'Between IT and OT an <b>industrial DMZ</b> (level 3.5) is built, and the <b>historian</b> – the data middleman – goes in it.'},
  {glow:c13g('plc','--amber')+c13g('dio','--amber')+c13g('hist','--amber'),dyn:c13pkt('M 510 144 L 510 56 L 366 56','--amber')+c13lbl(430,211,'OT side: data collection into the historian','--amber'),cap:'From the <b>OT side</b> the historian continuously collects and stores production values.'},
  {glow:c13g('it','--blue')+c13g('fw','--blue')+c13g('hist','--blue'),dyn:c13pkt('M 85 62 L 210 110 L 335 62','--blue')+c13lbl(160,211,'IT side: queries only the historian','--blue'),cap:'From the <b>IT side</b> the authorized query the historian (a database query). <b>No rule allows IT → PLC.</b>'},
  {glow:c13g('fw','--green')+c13g('hist','--green'),dyn:c13lbl(430,108,'data via a middleman, never direct ✓','--green'),cap:'The principle of OT security: <b>data via a middleman in the DMZ, never a direct link</b> between a dirty and a sensitive network.'}
]);}
/* ---------- L3M1 — Modbus: a protocol without a lock ---------- */
function renderC13Modbus(){return c13P('otg',
  'What do OT devices speak to each other? The most widespread industrial protocol is <b>Modbus</b> – born in <b>1979</b> for serial lines, later given the network form <b>Modbus/TCP</b> on port <b>502</b>. It is beautifully simple: ‘read register 40001’, ‘write value 75 into register 40002’. But that simplicity has a dark side: Modbus has <b>no authentication at all</b>. No password, no verification, no encryption. The PLC executes a command from <b>anyone</b> able to connect to port 502 – the protocol does not distinguish whether the writer is the authorized HMI or an attacker’s laptop. Write ‘open the valve fully’ and the PLC opens it. This is not an implementation bug fixable by a patch – <b>the protocol is designed that way</b>: in 1979 the network was a few meters of wire between the control room and the machine, and nobody imagined a stranger could be on it. And it is not just Modbus: other industrial protocols (DNP3, Profinet, S7) are similarly ‘trusting’. Now you see in full force why the segmentation from lesson 2 is so essential: when the protocol cannot say ‘no’, the <b>network</b> must say it instead – the only real defense is that <b>no unauthorized party ever reaches port 502</b>.',
  [['Modbus/TCP (502)','the most widespread industrial protocol (from 1979); reads/writes PLC registers on port 502.'],['no authentication','no password, no verification – the PLC executes a command from anyone who connects. The protocol is designed that way.'],['the network as the lock','when the protocol cannot say ‘no’, the network must: no unauthorized party may reach port 502.']]);}
function mountC13Modbus(){c13Mount('otg',[
  {glow:c13g('hmi','--green')+c13g('plc','--green'),dyn:c13pkt('M 366 160 L 494 160','--green')+c13lbl(430,211,'Modbus/TCP: ‘write register’ (port 502)','--green'),cap:'<b>Modbus/TCP</b> (port 502): the HMI reads and writes PLC registers – ‘read the temperature’, ‘set the valve’.'},
  {glow:c13g('plc','--red'),dyn:c13lbl(430,211,'no password, no verification ⚠','--red'),cap:'The dark side: Modbus has <b>no authentication</b>. The PLC executes a command from <b>anyone</b> on port 502 – by design (1979).'},
  {glow:c13g('eng','--red')+c13g('fw','--red')+c13g('hmi','--red')+c13g('plc','--red'),dyn:c13pkt('M 85 154 L 195 116','--red')+c13pkt('M 366 160 L 494 160','--red')+c13lbl(160,211,'the PLC would obey a stranger’s write too','--red'),cap:'The protocol cannot tell the authorized HMI from an attacker’s laptop. ‘Open the valve fully’ – and the PLC obeys.'},
  {glow:c13g('fw','--green')+c13g('plc','--green'),dyn:c13lbl(430,211,'defense = no stranger reaches 502','--green'),cap:'When the protocol cannot say ‘no’, the <b>network</b> says it: segmentation and the firewall keep the unauthorized away from port 502.'}
]);}
/* ---------- L3M2 — Where data flows: 502 vs 1433 ---------- */
function renderC13Flows(){return c13P('oth',
  'Let us merge lesson 2 and the previous module into one picture – what flows where in a well-built industrial network. Inside OT: <b>HMI ↔ PLC over Modbus 502</b> – the operator drives production, both sit in the same sensitive zone, this traffic never leaves. Data collection: <b>the historian reads values from the PLC</b> (Modbus 502) – the only one allowed to peek from the DMZ into OT, and only to read data. And the office: <b>IT-PC → historian over database port 1433</b> (SQL) – the manager sees production charts without getting anywhere near the PLC. Notice how the firewall distinguishes <b>by port and direction</b>: 1433 from IT into the DMZ yes, 502 from IT to anywhere NO – port 502 never crosses the OT/DMZ boundary outward. This ‘what is allowed’ set has a name you know from the course <i>Network security</i>: a <b>flow whitelist</b>. In OT it is especially effective because an industrial network is <b>boring and predictable</b>: the same devices exchange the same messages over and over, no web browsing. The list of legitimate flows fits on one page – and everything else is suspicious. You may have already seen exactly this topology in the simulator: the <b>‘OT/ICS network – IT/OT segmentation’</b> preset. In the next module you will verify the rules on it.',
  [['502 vs 1433','Modbus 502 stays in OT/DMZ; the office may only reach the historian’s database port 1433.'],['flow whitelist','an OT network is predictable – the list of legitimate flows is short and everything else is suspicious.']]);}
function mountC13Flows(){c13Mount('oth',[
  {glow:c13g('hmi','--green')+c13g('plc','--green'),dyn:c13pkt('M 366 160 L 494 160','--green')+c13lbl(430,211,'inside OT: HMI ↔ PLC (Modbus 502)','--green'),cap:'Inside OT: <b>HMI ↔ PLC</b> over Modbus 502. Both in the same sensitive zone – this traffic never leaves.'},
  {glow:c13g('plc','--amber')+c13g('dio','--amber')+c13g('hist','--amber'),dyn:c13pkt('M 510 144 L 510 56 L 366 56','--amber')+c13lbl(430,108,'collection: PLC → historian','--amber'),cap:'Data collection: <b>the historian reads PLC values</b> – the only allowed peek from the DMZ into OT, data only.'},
  {glow:c13g('it','--blue')+c13g('fw','--blue')+c13g('hist','--blue'),dyn:c13pkt('M 85 62 L 210 110 L 335 62','--blue')+c13lbl(160,211,'office: IT → historian (SQL 1433)','--blue'),cap:'The office: <b>IT-PC → historian on port 1433</b> (SQL). The manager sees charts and never nears the PLC.'},
  {glow:c13g('fw','--red'),dyn:c13lbl(160,211,'502 from IT: NEVER (flow whitelist)','--red'),cap:'The firewall distinguishes port and direction: 1433 from IT yes, <b>502 from IT never</b>. OT is predictable → a short flow whitelist.'}
]);}
/* ---------- L3M3 — Verify it in the simulator ---------- */
function renderC13Verify(){return c13P('oti',
  'Theory is nice, but this simulator exists so you can <b>touch it</b>. The whole architecture from the last two lessons is ready for you: in the <b>Templates</b> menu open the <b>‘OT/ICS network – IT/OT segmentation’</b> preset. You will find exactly our scene: an IT LAN, the inter-firewall, an industrial DMZ with the historian and an OT LAN with the PLC and HMI. What to try? In the right-hand <b>Traffic Test</b> panel pick a <b>Source (from)</b> and a <b>Destination</b> (protocol and port under Advanced) and click <b>▸ Test traffic</b>: (1) <b>IT-PC → PLC on port 502</b> – it must end <b>blocked</b> at the firewall; this very rule protects production from the office. (2) <b>IT-PC → historian on port 1433</b> – it must <b>pass</b>; that is how the manager gets his numbers. (3) <b>Historian → PLC on 502</b> – passes; that is the allowed data collection. Then open the firewall rules and note the <b>default-deny</b> policy: the list of allowed flows is short, everything else falls. And if you are up for it, try the <b>‘OT/ICS segmentation’ challenge</b> in Tasks: you get a broken industrial network and your job is to build the IT/OT boundary yourself. Learn to read a blocked packet as <b>good news</b>: in OT every ‘blocked’ in the right place is one path an attacker cannot take to a valve.',
  [['Traffic Test','the simulator panel: pick a source and destination, click "Test traffic" and verify: IT→PLC:502 blocked, IT→historian:1433 passes.'],['blocked = good news','in OT every ‘blocked’ in the right place is a path an attacker cannot take to a valve.']]);}
function mountC13Verify(){c13Mount('oti',[
  {glow:c13g('it','--red')+c13g('fw','--red'),dyn:c13pkt('M 85 62 L 195 104','--red')+c13lbl(160,211,'test 1: IT → PLC:502 → blocked ✓','--red'),cap:'<b>Test 1:</b> IT-PC → PLC on port 502. The packet must end <b>blocked at the firewall</b> – the office must not reach the PLC.'},
  {glow:c13g('it','--green')+c13g('fw','--green')+c13g('hist','--green'),dyn:c13pkt('M 85 62 L 210 110 L 335 62','--green')+c13lbl(160,211,'test 2: IT → historian:1433 → passes ✓','--green'),cap:'<b>Test 2:</b> IT-PC → historian on 1433 must <b>pass</b> – this is how the office gets production numbers.'},
  {glow:c13g('hist','--amber')+c13g('fw','--amber')+c13g('hmi','--amber')+c13g('plc','--amber'),dyn:c13pkt('M 335 62 L 225 104','--amber')+c13pkt('M 366 160 L 494 160','--amber')+c13lbl(430,108,'test 3: data collection passes','--amber'),cap:'<b>Test 3:</b> historian → PLC on 502 passes – the allowed data collection. Nothing else leads into OT.'},
  {glow:c13g('fw','--cyan'),dyn:c13lbl(160,211,'the OT/ICS preset + the “OT/ICS segmentation” challenge','--cyan'),cap:'Open the <b>OT/ICS network</b> template, review the rules (default-deny) – then try the challenge where you build the boundary yourself.'}
]);}
/* ---------- L4M1 — The diode: physics instead of rules ---------- */
function renderC13Diode(){return c13P('otj',
  'The firewall from lesson 2 is <b>software</b>: it decides by rules. And software can have a bug, someone can add a rule by mistake, the admin password can leak. For the most critical operations there is a harder caliber: the <b>data diode</b>. It is named after the electronic component that passes current one way only – and that is exactly what it does with network traffic. But it is not a rule in a config: it is a <b>physical construction</b>. Picture an optical fiber with <b>only a transmitter</b> (LED/laser) on one side and <b>only a receiver</b> on the other. Data physically flows left to right – and the reverse is <b>impossible</b>, just as you cannot speak into a loudspeaker and expect the radio to hear you. No misconfiguration, no stolen admin account, no zero-day flips that direction – <b>physics cannot be hacked</b>. Note the fundamental difference from a firewall: a firewall <b>decides</b> (‘this packet yes, that one no’) and can be wrong; the diode <b>decides nothing</b> – the other direction simply does not exist. The price is ruthlessness: not even a TCP acknowledgment passes back through the diode (that too is return traffic! – you know acknowledgments from the ISO/OSI and TCP/IP map course), so it needs special one-way protocols. Where it pays off and how it is wired is in the next module.',
  [['data diode','a physically one-way link (transmitter → receiver); the reverse direction does not exist and cannot be enabled or hacked.'],['firewall vs diode','a firewall decides by rules and can err; a diode decides nothing – the other direction is physically absent.']]);}
function mountC13Diode(){c13Mount('otj',[
  {glow:c13g('it','--amber')+c13g('fw','--amber')+c13g('hmi','--amber'),dyn:c13pkt('M 85 62 L 195 104','--amber')+c13pkt('M 225 116 L 335 154','--amber','1.4s')+c13lbl(210,78,'a rule lets it in – or gets it wrong','--amber')+c13lbl(160,211,'a firewall = software and rules','--amber'),cap:'A firewall <b>decides by rules</b> – and software can have bugs, rules mistakes, passwords leaks.'},
  {glow:c13g('plc','--lime')+c13g('dio','--lime'),dyn:c13pkt('M 510 144 L 510 72','--lime')+c13lbl(534,108,'↑','--lime')+c13lbl(430,108,'the diode: physically one direction','--lime'),cap:'A <b>data diode</b>: only a transmitter on one side, only a receiver on the other. The reverse direction <b>physically does not exist</b>.'},
  {glow:c13g('plc','--green')+c13g('dio','--green')+c13g('hist','--green'),dyn:c13pkt('M 510 144 L 510 56 L 366 56','--green')+c13lbl(430,211,'data flows out – never in','--green'),cap:'Production data flows <b>out</b> through the diode. No config or stolen account flips the direction – <b>physics cannot be hacked</b>.'},
  {glow:c13g('hist','--amber')+c13g('dio','--amber'),dyn:c13pkt('M 366 56 L 488 56','--amber')+c13lbl(468,42,'✕','--red')+c13lbl(430,30,'TCP ACK back → stopped at the diode','--amber')+c13lbl(430,108,'the price: not even a TCP ACK returns','--amber'),cap:'The price of ruthlessness: <b>not even a TCP acknowledgment</b> passes back – the diode needs special one-way protocols.'}
]);}
/* ---------- L4M2 — Monitoring out, no path in ---------- */
function renderC13OneWay(){return c13P('otk',
  'What good is a link you cannot answer through? Exactly one thing – and in OT it is golden: <b>letting production data out without creating any path in</b>. Recall the dilemma from lesson 2: production needs to share numbers (supervision, reporting, diagnostics), but every link toward OT is a risk. A firewall solves it with rules – a diode solves it <b>absolutely</b>. You see the wiring on the scene: the PLC sends values (temperatures, states, alarms) <b>through the diode</b> into the historian in the DMZ; from the historian IT reads them, the monitoring center, even a cloud. If an attacker took over the historian, the IT network, the whole internet – <b>they cannot reach the PLC through the diode</b>, because the inbound direction physically does not exist. Monitoring works, remote control from outside is impossible. Of course it costs something: (1) through a diode <b>nothing can be controlled or fixed remotely</b> – a command inward is also a ‘path inward’; a service intervention needs physical presence or a separately guarded channel (lesson 5 shows why that is sensitive). (2) One-way protocols are <b>special and pricier</b> – the sending side cannot know the data arrived, so it sends it repeatedly with checksums. That is why the diode does not replace the firewall everywhere – it is deployed where the risk of an inbound direction is <b>unacceptable</b>. Where exactly is the last module of this lesson.',
  [['monitoring out','the diode lets production values out to the historian/monitoring without creating a path in.'],['the price of one-way','no remote control or service through the diode; one-way protocols resend data with checksums.']]);}
function mountC13OneWay(){c13Mount('otk',[
  {glow:c13g('plc','--green')+c13g('dio','--green')+c13g('hist','--green'),dyn:c13pkt('M 510 144 L 510 56 L 366 56','--green')+c13lbl(430,211,'PLC → diode → historian (out only)','--green'),cap:'The PLC sends values <b>through the diode</b> to the historian in the DMZ. IT and monitoring read them from there.'},
  {glow:c13g('hist','--red')+c13g('dio','--red'),dyn:c13pkt('M 366 56 L 488 56','--red')+c13lbl(468,42,'✕','--red')+c13lbl(430,30,'attempt inbound → stopped at the diode','--red')+c13lbl(430,108,'historian compromised? no way in ⚠','--red'),cap:'Even if an attacker owned the historian, IT or the whole internet – <b>the inbound direction through the diode physically does not exist</b>.'},
  {glow:c13g('hist','--amber')+c13g('dio','--amber')+c13g('plc','--amber'),dyn:c13pkt('M 366 56 L 488 56','--amber')+c13lbl(468,42,'✕','--red')+c13lbl(430,30,'a command never reaches the PLC either','--amber')+c13lbl(430,211,'no remote control or service','--amber'),cap:'The price: <b>nothing can be controlled or fixed remotely</b> through the diode – a command in is also a path in.'},
  {glow:c13g('it','--cyan')+c13g('fw','--cyan')+c13g('hist','--cyan')+c13g('dio','--cyan'),dyn:c13pkt('M 85 62 L 195 104','--cyan')+c13pkt('M 225 104 L 335 62','--cyan','1.4s')+c13lbl(210,78,'a firewall is enough here','--cyan')+c13lbl(580,142,'only a diode here','--cyan')+c13lbl(430,108,'the diode where inbound is unacceptable','--cyan'),cap:'The diode does not replace the firewall everywhere – it goes where the risk of an inbound path is <b>unacceptable</b>.'}
]);}
/* ---------- L4M3 — Where the diode pays off ---------- */
function renderC13DiodeWhere(){return c13P('otl',
  'A data diode is expensive (tens of thousands of euros) and inconvenient – so where does it make sense? Where a breach of the control network would mean <b>catastrophe, not just damage</b>. The textbook example is <b>power plants</b>, especially nuclear: the reactor’s control system must send data to supervision and regulators, but the idea that <b>anything from outside</b> could send a command in is unacceptable – so one-way gateways there are often <b>required by regulation itself</b>. Likewise transmission-grid substations, water treatment plants, gas pipelines: critical infrastructure where the state prescribes how control networks may be connected. And uses beyond industry: <b>security monitoring</b> – logs from a sensitive network flow through a diode to a SOC (monitoring center), so analysts see everything, yet even their own compromised workstation cannot touch the sensitive network; or military systems where a classified network may only <b>receive</b> data. Back to earth: an ordinary cookie factory usually does not need a diode – a well-configured default-deny firewall (lesson 2) is proportionate defense for it. <b>Risk analysis</b> decides: what is the worst possible harm if the inbound direction failed? If the answer is ‘explosion, deaths, cities without power’ – you buy a diode. If ‘production stops for a week’ – a firewall and good rules suffice. In the simulator you can add a diode from the device palette and try how a topology behaves when a link works one way only.',
  [['critical infrastructure','power plants, substations, water treatment – where a breach means catastrophe and regulation prescribes one-way gateways.'],['risk analysis','the worst possible harm decides: catastrophe → a diode; ‘production stops’ → a default-deny firewall suffices.']]);}
function mountC13DiodeWhere(){c13Mount('otl',[
  {glow:c13g('dio','--lime')+c13g('plc','--lime'),dyn:c13lbl(430,108,'power plants: diode by regulation','--lime'),cap:'<b>Power plants</b> (especially nuclear), substations, water treatment: a breach = catastrophe, one-way gateways often required by regulation.'},
  {glow:c13g('plc','--cyan')+c13g('dio','--cyan')+c13g('hist','--cyan'),dyn:c13pkt('M 510 144 L 510 56 L 366 56','--cyan')+c13lbl(430,211,'logs → SOC: sees all, touches nothing','--cyan'),cap:'Beyond industry: <b>logs flow to the SOC</b> through a diode – analysts see everything, they cannot touch the sensitive network.'},
  {glow:c13g('fw','--green'),dyn:c13lbl(160,211,'an ordinary factory: a firewall suffices','--green'),cap:'An ordinary factory usually needs no diode – a <b>default-deny firewall</b> is proportionate. Risk analysis decides.'},
  {glow:c13g('dio','--amber'),dyn:c13lbl(430,108,'try it: the diode is in the palette','--amber'),cap:'In the simulator add a diode from the device palette and watch how the topology behaves with a one-way link.'}
]);}
/* ---------- L5M1 — Stuxnet: the attack that moved iron ---------- */
function renderC13Stuxnet(){return c13P('otm',
  'The story that splits OT security into ‘before’ and ‘after’. Around 2010 Iran was enriching uranium at the underground Natanz plant – thousands of fast-spinning centrifuges driven by PLCs. The facility was <b>disconnected from the internet</b> (a so-called air gap), and yet malware got in – known today as <b>Stuxnet</b>. How? Via <b>USB sticks and service technicians’ laptops</b> – it beat the air gap not through the network but through people. Inside, Stuxnet showed why it is still the textbook case: it sought no data, it sought a <b>specific PLC model</b> with a specific centrifuge configuration. Once found, it began <b>altering speeds</b>: briefly accelerate past the safe limit, return to normal, repeat weeks later. And it covered its tracks brilliantly: it <b>replayed recorded normal values</b> to the control-room operators, so the HMI showed calm while the centrifuges were physically destroying themselves. The result: hundreds of wrecked centrifuges, the program delayed by years – <b>software broke iron</b>. Three lessons to take away: (1) an <b>air gap is not absolute</b> – a USB stick, a service laptop or a supplier jumps it; (2) an attacker may go after the <b>physical process</b>, not data; (3) if your HMI can lie to you, you need <b>independent monitoring</b> of what is really happening in the network and process (lesson 6). Stuxnet was a state operation with huge resources – but the techniques it demonstrated have been imitated by more ordinary attackers ever since.',
  [['Stuxnet','malware (uncovered 2010) that entered Iran’s enrichment plant via USB and wrecked centrifuges by altering PLC speeds.'],['air gap','physically disconnecting a network from the internet; not absolute – a USB stick, service laptop or supplier crosses it.'],['a lying HMI','Stuxnet replayed normal values to operators; hence the need for independent process monitoring.']]);}
function mountC13Stuxnet(){c13Mount('otm',[
  {glow:c13g('eng','--red'),dyn:c13lbl(160,211,'USB and a service laptop jump the air gap','--red'),cap:'Natanz was <b>disconnected from the internet</b> – Stuxnet got in via USB sticks and technicians’ laptops.'},
  {glow:c13g('eng','--red')+c13g('fw','--red')+c13g('hmi','--red')+c13g('plc','--red'),dyn:c13pkt('M 85 154 L 210 110 L 350 160 L 494 160','--red')+c13lbl(430,211,'target: a specific PLC, alter speeds ⚠','--red'),cap:'Inside it sought a <b>specific PLC</b> driving centrifuges – and altered speeds: briefly past the limit, back, again weeks later.'},
  {glow:c13g('hmi','--amber'),dyn:c13lbl(430,211,'the HMI showed calm – replayed values','--amber'),cap:'It <b>replayed recorded normal values</b> to operators – the control room saw calm while centrifuges wrecked themselves.'},
  {glow:c13g('plc','--red'),dyn:c13lbl(430,211,'software broke iron','--red'),cap:'Hundreds of wrecked centrifuges. Lessons: the air gap is not absolute, the target may be the <b>physical process</b> – and the HMI can lie.'}
]);}
/* ---------- L5M2 — Ransomware: production stops via IT ---------- */
function renderC13Ransom(){return c13P('otn',
  'Stuxnet is the extreme – the more common scenario of recent years is more mundane: <b>ransomware</b>. And here comes an unexpected point: production often stops <b>without the attacker ever entering the OT network</b>. How? Recall what production depends on <b>around</b> OT: order planning, warehouses and shipping, recipes, invoicing – all of it runs in <b>IT</b>. When ransomware encrypts the IT network, the plant still has working PLCs and HMIs, but <b>does not know what to make, from what, or where to ship it</b>. And there is a second, even more direct reason: when the company fears the infection will spread across the boundary into OT, it <b>shuts production down preventively itself</b>. Exactly that happened in real cases: aluminum maker Norsk Hydro (2019) switched smelters to manual control, Colonial Pipeline (2021) stopped the largest US fuel pipeline – not because ransomware drove valves, but because IT was crippled and certainty was missing. Lessons for defense: (1) <b>the IT/OT boundary from lesson 2 is also a firebreak</b> – the cleaner and better audited, the better the chance production survives an IT incident; (2) OT must be able to <b>run a while without IT</b> (manual mode, local recipe copies) – that is a continuity-plan question; (3) <b>backups of the IT systems</b> production depends on are part of OT security even though they live in IT. Ransomware does not aim at valves – it aims at money. But it stops production all the same.',
  [['ransomware','extortion malware encrypting systems; it often stops production by crippling IT, not by entering OT.'],['preventive shutdown','the company halts production itself, fearing spread across the boundary into OT (Norsk Hydro, Colonial Pipeline).'],['the boundary as a firebreak','a clean, audited IT/OT boundary raises the chance production survives an IT incident without an outage.']]);}
function mountC13Ransom(){c13Mount('otn',[
  {glow:c13g('it','--red'),dyn:c13lbl(160,211,'ransomware encrypts IT','--red'),cap:'Ransomware encrypts the <b>IT network</b>: planning, warehouses, recipes, invoicing – everything production depends on.'},
  {glow:c13g('plc','--amber')+c13g('hmi','--amber'),dyn:c13lbl(430,211,'PLCs run – but nobody knows what to make','--amber'),cap:'OT is untouched: PLCs and HMIs work. But the plant <b>does not know what to make, from what, or where to ship it</b>.'},
  {glow:c13g('it','--red')+c13g('fw','--red'),dyn:c13lbl(160,211,'fear of spread → shut down yourself ⚠','--red'),cap:'And production is often <b>shut down preventively</b> for fear of spread (Norsk Hydro 2019, Colonial Pipeline 2021).'},
  {glow:c13g('fw','--green')+c13g('hmi','--green'),dyn:c13lbl(430,211,'defense: firm boundary + running without IT + backups','--green'),cap:'Defense: a <b>clean IT/OT boundary</b> (a firebreak), OT able to run a while without IT, and backups of production’s IT systems.'}
]);}
/* ---------- L5M3 — The insider, USB and the service laptop ---------- */
function renderC13Insider(){return c13P('oto',
  'Segmentation from lesson 2 guards <b>network paths</b>. But paths into OT also exist that no firewall shows – <b>people</b> carry them. Path one: the <b>USB stick</b>. A technician needs to load a new program into the PLC or update the HMI – and the network is (rightly!) separated, so he carries it on a stick. That same stick was in his home computer yesterday… exactly how Stuxnet traveled. Path two: the <b>service laptop</b>. An external technician tours dozens of plants with one laptop, plugging it straight into OT networks – an ideal carrier. Path three: the <b>insider</b> – a disgruntled or bribed employee who has legitimate OT access; the most famous case: Maroochy Shire (Australia 2000), where a former contractor’s technician remotely released sewage into rivers and parks – dozens of interventions before he was caught. What to do? For sticks: <b>ban on foreign media</b> + a scanning station (kiosk) where every stick is checked for malware before entering the plant, or company ‘vetted’ sticks for OT only. For laptops: the vendor gets <b>your</b> vetted laptop, or their machine may only join a separated service network. For insiders: <b>least privilege</b> (a technician sees only his line), immediate access removal on departure, and logs of who accessed what and when – without them Maroochy took months to investigate. The common denominator: <b>rules for people and devices</b> matter in OT as much as rules on the firewall.',
  [['media control','a ban on foreign sticks + a kiosk that scans every medium for malware before it enters OT.'],['insider','someone with legitimate access (employee, contractor); defense: least privilege, access removal, logs.'],['Maroochy Shire','Australia 2000: a former contractor technician remotely released sewage – the classic OT insider case.']]);}
function mountC13Insider(){c13Mount('oto',[
  {glow:c13g('hmi','--red'),dyn:c13lbl(430,211,'a USB stick bypasses the firewall','--red'),cap:'A <b>USB stick</b> reaches the HMI/PLC outside the network – no firewall ever sees it. Yesterday it was in a home computer…'},
  {glow:c13g('eng','--red')+c13g('fw','--red')+c13g('hmi','--red'),dyn:c13pkt('M 85 154 L 210 110 L 335 154','--red')+c13lbl(160,211,'the service laptop: a carrier between plants','--red'),cap:'An external technician’s <b>service laptop</b> tours dozens of plants, plugging straight into OT – an ideal carrier.'},
  {glow:c13g('eng','--amber')+c13g('plc','--amber'),dyn:c13lbl(430,211,'the insider: has legal access (Maroochy 2000)','--amber'),cap:'The <b>insider</b> has legal access: at Maroochy Shire (2000) a former technician remotely released sewage into rivers.'},
  {glow:c13g('hmi','--green')+c13g('eng','--green'),dyn:c13lbl(430,211,'a media kiosk · a vetted laptop · logs','--green'),cap:'Defense: a kiosk scans every stick, the vendor gets your laptop, least privilege and who/when/what logs.'}
]);}
/* ---------- L5M4 — Vendor remote access ---------- */
function renderC13Vendor(){return c13P('otp',
  'The last big path inside is official and blessed by contract: <b>vendor remote access</b>. The line’s manufacturer needs to service it remotely – diagnostics, tuning, updates. Sounds reasonable – but think through what it means: <b>a hole through all your carefully built boundaries</b>, leading from the internet straight to the PLC. And often in the worst form: a permanently-on VPN, a shared ‘service’ account for all the vendor’s technicians, full access to the whole OT network, no record of what happened during the session. Why is that so dangerous? Compromise <b>one vendor</b> – and you hold keys to dozens of plants at once (exactly the reasoning behind supply-chain attacks). What does the safe version look like? (1) A <b>jump host</b>: the vendor never connects directly to the PLC but to a middleman in your DMZ, from which one proceeds (supervised) further – no direct internet→OT path. (2) <b>Just-in-time access</b>: the VPN is normally <b>off</b>; your operator enables it for an announced service window and disables it afterwards. (3) <b>Personal accounts and session recording</b>: you know which technician did what – remember Maroochy. (4) <b>Least privilege</b>: access only to the line the vendor services, not the whole OT network. Check the same at home in miniature: how many ‘temporary’ remote accesses (TeamViewer on the heating, the vendor cloud of your solar panels) do you keep permanently on?',
  [['jump host','a middleman in the DMZ: the vendor connects to it, never directly to the PLC – no direct internet→OT path.'],['just-in-time access','the VPN is normally off; enabled for an announced service window and disabled afterwards.'],['session recording','personal accounts + a record of which technician did what; a shared ‘service’ account is blindness.']]);}
function mountC13Vendor(){c13Mount('otp',[
  {glow:c13g('eng','--red')+c13g('fw','--red')+c13g('plc','--red')+c13g('hmi','--red'),dyn:c13pkt('M 85 154 L 210 110 L 350 160 L 494 160','--red')+c13lbl(160,211,'a vendor’s always-on VPN to the PLC ⚠','--red'),cap:'The worst form: an <b>always-on VPN</b>, a shared account, full OT access, no record. A hole through every boundary.'},
  {glow:c13g('eng','--amber'),dyn:c13lbl(160,211,'1 vendor = keys to dozens of plants','--amber'),cap:'Compromise <b>one vendor</b> and you hold keys to dozens of plants – the supply-chain attack logic.'},
  {glow:c13g('eng','--green')+c13g('fw','--green')+c13g('hist','--green'),dyn:c13pkt('M 85 154 L 210 110 L 335 62','--green')+c13lbl(160,211,'safely: a jump host in the DMZ, supervised','--green'),cap:'The safe version: the vendor lands on a <b>jump host in the DMZ</b>, and only from there (supervised) onward. No direct internet→OT path.'},
  {glow:c13g('fw','--green'),dyn:c13lbl(160,211,'VPN off; enabled for announced service','--green'),cap:'Plus <b>just-in-time</b>: the VPN goes on for announced service and off again. Personal accounts, session recording, least privilege.'}
]);}
/* ---------- L6M1 — Inventory: you don't protect what you don't know ---------- */
function renderC13Inventory(){return c13P('otq',
  'OT defense starts with a question that sounds trivial yet few plants can answer in practice: <b>what exactly do we have on the network?</b> Industrial networks grew for decades: a line from one vendor, an extension from another, a ‘temporary’ link from 2009 that is still there. Nobody has a complete list. Yet it is the foundation of everything: <b>you cannot protect what you do not know about</b>. A firewall rule for a device missing from the list? Segmenting a network nobody mapped? Impossible. That is why step one of every OT security project is the <b>asset inventory</b>: what it is (PLC, HMI, sensor…), where it is (hall, cabinet), what firmware it runs, whom it talks to (which flows – recall the whitelist from lesson 3) and <b>who is responsible for it</b>. The last point hurts most: for a twenty-year-old line, often nobody knows who maintains it anymore. How to get the list? In IT you would run a scanner – in OT that can be dangerous (as the next module shows). So OT inventory is built mainly <b>passively</b>: by listening to network traffic (who talks to whom, over which protocol) and by tedious legwork – going through documentation, cabinets, labels. The reward: only on top of a complete list does everything else make sense – segmentation, rules, monitoring and the recovery plan.',
  [['asset inventory','a complete device list: what, where, which firmware, whom it talks to and who is responsible.'],['you can’t protect the unknown','without the inventory you cannot build segmentation, rules or monitoring – it is step one.']]);}
function mountC13Inventory(){c13Mount('otq',[
  {glow:c13g('plc','--amber')+c13g('hmi','--amber'),dyn:c13lbl(430,211,'what exactly is on the network?','--amber'),cap:'The industrial network grew for decades – the ‘temporary’ link from 2009 is still there. Nobody has a complete list.'},
  {glow:c13g('fw','--red'),dyn:c13lbl(160,211,'no list, no rules ⚠','--red'),cap:'<b>You cannot protect what you do not know about</b>: no rule for an unmapped device, no segmentation design.'},
  {glow:c13g('hist','--cyan')+c13g('dio','--cyan')+c13g('plc','--cyan'),dyn:c13pkt('M 510 144 L 510 56 L 366 56','--cyan')+c13lbl(430,108,'passively: listen who talks to whom','--cyan'),cap:'In OT the inventory is built <b>passively</b>: listening to traffic (who with whom, which protocol) + documentation and labels.'},
  {glow:c13g('fw','--green')+c13g('plc','--green'),dyn:c13lbl(430,211,'on the list: segmentation, rules, monitoring','--green'),cap:'The reward: only over a complete list do segmentation, the flow whitelist, monitoring and recovery planning make sense.'}
]);}
/* ---------- L6M2 — Passive monitoring: why you don't scan in OT ---------- */
function renderC13Passive(){return c13P('otr',
  'In IT, <b>active scanning</b> is routine: a tool walks the network, ‘knocks’ on every address’s ports and learns what runs where. Trying the same in OT is a rookie mistake that can <b>stop production</b>. Why? Recall lesson 1: a PLC is a twenty-year-old computer with minimal memory and a fragile network stack, built to talk to <b>one HMI over a known protocol</b> – not to face a volley of odd packets from a scanner. Real consequences from practice: a PLC freezes after a scan and the line stops; a sensor reboots mid-process; an old print server in the hall starts spewing paper. In IT the same scan would knock over nothing – in OT it is a gamble. You already know the fix from the previous module: <b>passive monitoring</b>. The switch is set to <b>mirror traffic</b> (a SPAN/mirror port – a copy of everything flowing through; covered in detail in The Switch in Depth course) and the analyzer just <b>listens</b>: it transmits <b>nothing</b>, so it can break nothing. What can listening reveal? Surprisingly much – and here it helps that the OT network is <b>boring and predictable</b> (lesson 3): monitoring learns the normal (the HMI talks to the PLC, the historian collects data) and shouts on a <b>deviation</b>: a new unknown device, a Modbus write from an address that never wrote, a connection to the internet from OT. Remember Stuxnet: the HMI lied, but <b>the network traffic did not</b> – independent passive monitoring is exactly the safety net Natanz lacked.',
  [['active scanning in OT','a packet volley can freeze a PLC or reboot a sensor mid-process – you do not scan in OT.'],['passive monitoring','the analyzer listens to a traffic copy (mirror/SPAN port) and transmits nothing – it can break nothing.'],['deviation from normal','OT is predictable; an alert = a new device, an unusual Modbus write, an OT-to-internet connection.']]);}
function mountC13Passive(){c13Mount('otr',[
  {glow:c13g('it','--red')+c13g('fw','--red')+c13g('hmi','--red')+c13g('plc','--red'),dyn:c13pkt('M 85 62 L 210 110 L 350 160 L 494 160','--red','1s')+c13lbl(160,211,'an active scan: a volley at everything ⚠','--red'),cap:'The IT habit: a scanner ‘knocks’ on all ports. In OT a gamble – the PLC’s fragile stack was not built for it.'},
  {glow:c13g('plc','--red'),dyn:c13lbl(430,211,'the PLC freezes after a scan → the line stops','--red'),cap:'Real consequences: a PLC freezes, a sensor reboots mid-process. <b>In OT you do not scan actively.</b>'},
  {glow:c13g('hmi','--cyan')+c13g('plc','--cyan'),dyn:c13pkt('M 366 160 L 494 160','--cyan')+c13lbl(430,211,'passively: a mirror port, just listens','--cyan'),cap:'<b>Passive monitoring</b>: the switch mirrors traffic (SPAN port), the analyzer only listens – transmits nothing, breaks nothing.'},
  {glow:c13g('eng','--amber')+c13g('fw','--amber')+c13g('hmi','--amber')+c13g('plc','--amber'),dyn:c13pkt('M 85 154 L 210 110 L 350 160 L 494 160','--amber')+c13lbl(160,211,'alert: a write from an address that never wrote','--amber'),cap:'OT is predictable → alert on deviation: a new device, an unusual Modbus write. The HMI can lie, <b>traffic does not</b>.'}
]);}
/* ---------- L6M3 — Zones, conduits and a recovery plan ---------- */
function renderC13Zones(){return c13P('ots',
  'Two last practical items for your OT toolkit. <b>First: zones and conduits.</b> The <b>IEC 62443</b> standard (the international norm for industrial system security – it is enough to know it exists and this is its core) formalizes what you built intuitively in this course: the network is split into <b>zones</b> – groups of devices of equal sensitivity (OT line 1, OT line 2, DMZ, IT) – and between zones you define <b>conduits</b>: guarded connecting channels, each with a written list of allowed flows. Recognize it? That is exactly our preset: IT / DMZ / OT zones, conduits through the inter-firewall, a whitelist of 1433 and 502. In the simulator you can even draw the zones – the <b>+ Zone</b> button on the canvas; do it, a visual boundary helps thinking. <b>Second: backups and recovery.</b> Even with perfect segmentation something will one day break – and OT recovery has a twist: you need to restore not just data but the <b>PLC programs</b> (the logic driving the machine) and the <b>configurations</b> of HMIs and network gear. Questions you must be able to answer <b>in advance</b>: Do we have a current copy of every PLC’s program? (After twenty years of tweaks, often the only copy lives in the PLC itself.) Can we load it back, and do we know how long that takes? Have we tried it <b>as a drill</b>? A recovery plan nobody ever tested is just paper. The module’s closing point: zones limit <b>how far a problem spreads</b>; backups decide <b>how fast you recover from it</b>.',
  [['zones and conduits (IEC 62443)','zones = device groups of equal sensitivity; conduits = guarded channels between them with written flows.'],['PLC program backup','the PLC logic and configs must be restorable too; after years of tweaks the only copy often lives in the PLC.'],['tested recovery','a recovery plan nobody ever drilled is just paper.']]);}
function mountC13Zones(){
  var zones=function(){return c13lbl(70,20,'IT zone','--blue')+c13lbl(350,20,'DMZ zone','--violet')+c13lbl(560,190,'OT zone','--amber');};
  c13Mount('ots',[
  {glow:c13g('it','--blue')+c13g('hist','--violet')+c13g('plc','--amber')+c13g('hmi','--amber'),dyn:zones()+c13lbl(160,211,'zones: IT / DMZ / OT (IEC 62443)','--blue'),cap:'<b>Zones</b>: device groups of equal sensitivity – IT, DMZ, OT. IEC 62443 formalizes what we built all along.'},
  {glow:c13g('it','--green')+c13g('fw','--green')+c13g('hist','--green'),dyn:zones()+c13pkt('M 85 62 L 195 104','--green')+c13pkt('M 225 104 L 335 62','--green','1.4s')+c13lbl(210,78,'TCP 1433 ✓','--green')+c13lbl(160,211,'a conduit = a guarded channel, flows written down','--green'),cap:'Between zones run <b>conduits</b>: guarded channels, each with a flow whitelist (1433, 502). In the sim: the + Zone button.'},
  {glow:c13g('plc','--amber'),dyn:zones()+c13lbl(468,124,'the program inside the PLC ⚠','--amber')+c13lbl(430,211,'the only program copy often lives in the PLC ⚠','--amber'),cap:'OT recovery: besides data also <b>PLC programs</b> and configs. After years of tweaks the only copy often lives in the PLC.'},
  {glow:c13g('plc','--green')+c13g('hmi','--green'),dyn:zones()+c13pkt('M 494 160 L 366 160','--green')+c13lbl(430,120,'the program backup out of the PLC','--green')+c13lbl(430,211,'back up programs + drill the recovery','--green'),cap:'Back up PLC programs and <b>drill the recovery</b>. Zones limit the spread; backups decide the speed of return.'}
]);}
/* ---------- L6M4 — Summary: OT survives even your bad day ---------- */
function renderC13Summary(){return c13P('ott',
  'The course ends – let us assemble industrial network defense into one picture. <b>Think differently</b>: in OT availability &gt; integrity &gt; confidentiality; devices are old and unpatched, so you protect the network around them, not the devices themselves (lesson 1). <b>Segment</b>: Purdue levels, an IT/OT boundary with a default-deny firewall, an industrial DMZ with the historian as middleman – no rule ever leads from IT straight into OT (lesson 2). <b>Do not trust the protocols</b>: Modbus and friends have no authentication; whoever reaches port 502 is in control – the only real defense is that they never reach it (lesson 3). <b>Where the risk is unacceptable, use physics</b>: a data diode lets monitoring out and nothing leads in (lesson 4). <b>Count on people</b>: Stuxnet arrived on a stick, ransomware stops production through IT, the insider has legal access and a vendor VPN is a hole through every boundary – a media kiosk, a jump host, just-in-time access, logs (lesson 5). <b>And operate</b>: the inventory (you cannot protect the unknown), passive monitoring instead of scanning, zones and conduits, tested PLC program backups (lesson 6). Notice the common thread: almost none of this was new technology – the firewall, DMZ, whitelist and backups you know from earlier courses. OT security is largely <b>discipline</b>: familiar tools applied with respect for a world where a mistake does not crash an app but stops a plant. If you saved the ‘OT/ICS segmentation’ challenge for the end – now is the time.',
  [['OT security = discipline','familiar tools (firewall, DMZ, whitelist, backups) applied with respect for production.'],['the course thread','think differently → segment → distrust protocols → physics where needed → count on people → operate.']]);}
function mountC13Summary(){c13Mount('ott',[
  {glow:c13g('it','--green')+c13g('fw','--green')+c13g('hist','--green'),dyn:c13pkt('M 85 62 L 210 110 L 335 62','--green')+c13lbl(160,211,'segmentation: IT only to the historian','--green'),cap:'<b>Segment</b>: an IT/OT boundary with default-deny, a DMZ with the historian as middleman. No rule leads from IT into OT.'},
  {glow:c13g('plc','--amber')+c13g('hmi','--amber'),dyn:c13pkt('M 366 160 L 494 160','--amber')+c13lbl(430,211,'lockless protocols → the network guards','--amber'),cap:'<b>Do not trust protocols</b>: Modbus has no authentication. Whoever reaches port 502 controls – so keep them from reaching it.'},
  {glow:c13g('plc','--lime')+c13g('dio','--lime')+c13g('hist','--lime'),dyn:c13pkt('M 510 144 L 510 56 L 366 56','--lime')+c13lbl(430,108,'physics + people: diode, kiosk, jump host','--lime'),cap:'<b>Physics where risk is unacceptable</b> (the diode) – and <b>people</b>: a media kiosk, a jump host, just-in-time, logs.'},
  {glow:c13g('it','--cyan')+c13g('fw','--cyan')+c13g('hist','--cyan')+c13g('hmi','--cyan')+c13g('plc','--cyan')+c13g('dio','--cyan')+c13g('eng','--cyan'),dyn:c13lbl(160,211,'operate: inventory, passive monitoring, backups','--cyan'),cap:'<b>And operate</b>: inventory, passive monitoring, zones and conduits, tested backups. Congratulations – now the simulator challenge!'}
]);}

